"""
Academic Writer — Computational Style Metrics (core)

Computes the `computationalMetrics` shape consumed by
src/skills/write/references/style-fingerprint-rubric.md:

    computationalMetrics.sentenceLevel.length.{mean,stdev}
    computationalMetrics.sentenceLevel.distribution
    computationalMetrics.sentenceLevel.passiveVoiceFrequency
    computationalMetrics.sentenceLevel.firstPersonFrequency
    computationalMetrics.paragraphStructure.length.{mean,stdev}
    computationalMetrics.paragraphStructure.sentencesPerParagraph.{mean,stdev}
    computationalMetrics.transitions.frequencyPerParagraph
    computationalMetrics.transitions.byCategory
    computationalMetrics.vocabulary.{typeTokenRatio,avgWordLength}

All heuristics are deliberately simple (regex/lexicon based, no NLP models)
so the script stays stdlib-only and fully deterministic, per src/CLAUDE.md.
"""

from __future__ import annotations

import re
import statistics
from typing import Optional

HEBREW_RANGE = r"֐-׿"
HEBREW_CHAR_RE = re.compile(f"[{HEBREW_RANGE}]")
WORD_RE = re.compile(rf"[{HEBREW_RANGE}A-Za-z']+")
SENTENCE_SPLIT_RE = re.compile(r"(?<=[.!?])\s+")
PARAGRAPH_SPLIT_RE = re.compile(r"\n\s*\n")

# Hebrew acronyms and abbreviations carry gershayim before the last letter
# (שד"ל, הרמב"ם, חז"ל, רש"י). Writers type an ASCII double quote for it, and
# `"` is not in WORD_RE, so every such word was split into two fragments —
# measured on a real corpus, 654 occurrences across 243 distinct acronyms,
# leaving "שד" ranked 8th among content terms while שד"ל, the subject of that
# paper, did not appear at all. U+05F4 GERSHAYIM is already inside
# HEBREW_RANGE, so normalizing to it before tokenizing is enough. Only a quote
# flanked by Hebrew letters is converted: an ordinary quotation mark sits next
# to a space or punctuation and is left alone.
HEBREW_GERSHAYIM = "\u05f4"
_ASCII_QUOTE_AS_GERSHAYIM_RE = re.compile(
    rf'(?<=[{HEBREW_RANGE}])"(?=[{HEBREW_RANGE}])'
)

# First-person markers (Hebrew + English) — a researcher's authorial voice.
FIRST_PERSON_MARKERS = {
    "אני",
    "אנו",
    "אנחנו",
    "לדעתי",
    "לדעתנו",
    "אטען",
    "אציג",
    "אבחן",
    "אראה",
    "אסביר",
    "אבקש",
    "ברצוני",
    "ברצוננו",
    "טענתי",
    "אבחין",
    "ברשותי",
    "i",
    "we",
    "my",
    "our",
    "argue",
    "propose",
    "believe",
}

# Hebrew passive voice is NOT measured. The previous heuristic flagged any 3+
# letter word opening with נ or מ, which matches an enormous set of ordinary
# non-passive words (מחקר, מאמר, מקום, נושא...). Measured against a real
# corpus it returned 0.77 versus a 0.19 baseline and the contrastive layer
# confidently reported "distinctively_high" — steering the section-writer
# toward passive constructions the author does not use. Real nif'al/pu'al/
# huf'al detection needs morphological analysis, which this stdlib-only,
# model-free script cannot do (see module docstring), so the metric is
# reported as null for Hebrew-dominant corpora rather than guessed at: a
# wrong confident number is worse than an honest null, and
# compute_contrastive already degrades such a metric to "unavailable".
HEBREW_DOMINANCE_THRESHOLD = 0.1
# English passive: a form of "to be" followed by a past participle.
# English passive: a form of "to be" followed by a past participle.
_EN_PASSIVE_RE = re.compile(
    r"\b(is|are|was|were|been|being|be)\s+\w+ed\b", re.IGNORECASE
)

TRANSITION_CATEGORIES: dict[str, list[str]] = {
    "addition": [
        "בנוסף",
        "כמו כן",
        "יתרה מכך",
        "זאת ועוד",
        "גם כן",
        "moreover",
        "furthermore",
        "in addition",
        "additionally",
    ],
    "contrast": [
        "לעומת זאת",
        "אולם",
        "אך",
        "מנגד",
        "בניגוד ל",
        "however",
        "nevertheless",
        "on the other hand",
        "conversely",
    ],
    "causation": [
        "לכן",
        "משום כך",
        "כתוצאה מכך",
        "מאחר ש",
        "היות ש",
        "therefore",
        "thus",
        "consequently",
        "as a result",
    ],
    "exemplification": [
        "לדוגמה",
        "כגון",
        "למשל",
        "דוגמת",
        "for example",
        "for instance",
        "such as",
    ],
    "conclusion": [
        "לסיכום",
        "לבסוף",
        "אי לכך",
        "לפיכך",
        "בסיכומו של דבר",
        "in conclusion",
        "to summarize",
        "in summary",
        "finally",
    ],
}


def normalize_hebrew_quotes(text: str) -> str:
    """Convert an ASCII double quote used as gershayim into U+05F4."""
    return _ASCII_QUOTE_AS_GERSHAYIM_RE.sub(HEBREW_GERSHAYIM, text)


def tokenize_words(text: str) -> list[str]:
    return WORD_RE.findall(normalize_hebrew_quotes(text))


def split_sentences(text: str) -> list[str]:
    flat = " ".join(text.split())
    sentences = [s.strip() for s in SENTENCE_SPLIT_RE.split(flat) if s.strip()]
    return sentences


def split_paragraphs(text: str) -> list[str]:
    paragraphs = [p.strip() for p in PARAGRAPH_SPLIT_RE.split(text) if p.strip()]
    return paragraphs or ([text.strip()] if text.strip() else [])


def _mean_stdev(values: list[float]) -> dict[str, float]:
    if not values:
        return {"mean": 0.0, "stdev": 0.0, "min": 0, "max": 0}
    mean = statistics.fmean(values)
    stdev = statistics.pstdev(values) if len(values) > 1 else 0.0
    return {
        "mean": round(mean, 2),
        "stdev": round(stdev, 2),
        "min": min(values),
        "max": max(values),
    }


def _sentence_length_distribution(lengths: list[int]) -> dict[str, int]:
    dist = {"short": 0, "medium": 0, "long": 0}
    for length in lengths:
        if length <= 10:
            dist["short"] += 1
        elif length <= 20:
            dist["medium"] += 1
        else:
            dist["long"] += 1
    return dist


def _hebrew_share(sentences: list[str]) -> float:
    """Fraction of corpus tokens containing Hebrew characters."""
    words = [w for s in sentences for w in tokenize_words(s)]
    if not words:
        return 0.0
    hebrew = sum(1 for w in words if HEBREW_CHAR_RE.search(w))
    return hebrew / len(words)


def _passive_voice_frequency(sentences: list[str]) -> Optional[float]:
    """Share of sentences in the passive voice, or None when unmeasurable.

    Returns None for Hebrew-dominant text: see the HEBREW_DOMINANCE_THRESHOLD
    comment above. For Latin-script text the "to be" + past-participle regex
    is a usable proxy and a number is returned.
    """
    if not sentences:
        return 0.0
    if _hebrew_share(sentences) > HEBREW_DOMINANCE_THRESHOLD:
        return None
    passive_hits = sum(1 for s in sentences if _EN_PASSIVE_RE.search(s))
    return round(passive_hits / len(sentences), 4)


def _first_person_frequency(sentences: list[str]) -> float:
    if not sentences:
        return 0.0
    hits = 0
    for sentence in sentences:
        words_lower = {
            w.lower() if not HEBREW_CHAR_RE.search(w) else w
            for w in tokenize_words(sentence)
        }
        if words_lower & FIRST_PERSON_MARKERS:
            hits += 1
    return round(hits / len(sentences), 4)


def compute_sentence_level(sentences: list[str]) -> dict:
    lengths = [len(tokenize_words(s)) for s in sentences]
    passive = _passive_voice_frequency(sentences)
    result = {
        "length": _mean_stdev(lengths),
        "distribution": _sentence_length_distribution(lengths),
        "passiveVoiceFrequency": passive,
        "firstPersonFrequency": _first_person_frequency(sentences),
        "count": len(sentences),
    }
    if passive is None:
        result["passiveVoiceFrequencyNote"] = (
            "Not measured: reliable Hebrew nif'al/pu'al/huf'al detection needs "
            "morphological analysis unavailable to this stdlib-only script. "
            "Judge passive voice qualitatively by reading the corpus."
        )
    return result


def compute_paragraph_structure(paragraphs: list[str]) -> dict:
    word_lengths = [len(tokenize_words(p)) for p in paragraphs]
    sentence_counts = [len(split_sentences(p)) for p in paragraphs]
    return {
        "length": _mean_stdev(word_lengths),
        "sentencesPerParagraph": _mean_stdev(sentence_counts),
        "count": len(paragraphs),
    }


def compute_transitions(
    sentences: list[str], paragraph_count: int, word_count: int = 0
) -> dict:
    by_category: dict[str, dict[str, int]] = {cat: {} for cat in TRANSITION_CATEGORIES}
    total_hits = 0
    lowered_sentences = [s.lower() for s in sentences]
    for category, phrases in TRANSITION_CATEGORIES.items():
        for phrase in phrases:
            phrase_lower = phrase.lower()
            count = sum(1 for s in lowered_sentences if phrase_lower in s)
            if count:
                by_category[category][phrase] = count
                total_hits += count
    frequency_per_paragraph = (
        round(total_hits / paragraph_count, 4) if paragraph_count else 0.0
    )
    # frequencyPerParagraph is only comparable between two corpora whose
    # paragraphs are the same length. Measured case: a corpus averaging 53.8
    # words per paragraph against a baseline averaging 122.6 reads 8x low on
    # the per-paragraph rate and only ~1.1x low once normalized. This second
    # figure is the length-independent one. It is deliberately NOT added to
    # CONTRASTIVE_METRIC_PATHS — the published baseline carries no
    # per-1000-words value, so a contrastive entry for it would be
    # "unavailable" on every run.
    frequency_per_1000_words = (
        round(1000 * total_hits / word_count, 4) if word_count else 0.0
    )
    return {
        "frequencyPerParagraph": frequency_per_paragraph,
        "frequencyPer1000Words": frequency_per_1000_words,
        "byCategory": by_category,
        "totalHits": total_hits,
    }


def compute_vocabulary(words: list[str]) -> dict:
    if not words:
        return {
            "typeTokenRatio": 0.0,
            "avgWordLength": 0.0,
            "totalWords": 0,
            "uniqueWords": 0,
        }
    normalized = [w if HEBREW_CHAR_RE.search(w) else w.lower() for w in words]
    unique = set(normalized)
    avg_len = statistics.fmean(len(w) for w in words)
    return {
        "typeTokenRatio": round(len(unique) / len(normalized), 4),
        "avgWordLength": round(avg_len, 2),
        "totalWords": len(words),
        "uniqueWords": len(unique),
    }


def compute_computational_metrics(text: str) -> dict:
    sentences = split_sentences(text)
    paragraphs = split_paragraphs(text)
    words = tokenize_words(text)
    return {
        "sentenceLevel": compute_sentence_level(sentences),
        "paragraphStructure": compute_paragraph_structure(paragraphs),
        "transitions": compute_transitions(sentences, len(paragraphs), len(words)),
        "vocabulary": compute_vocabulary(words),
    }
